CREATE DATABASE IF NOT EXISTS resepin
  CHARACTER SET utf8mb4
  COLLATE utf8mb4_unicode_ci;
USE resepin;

CREATE TABLE IF NOT EXISTS categories (
    id TINYINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    name VARCHAR(50) NOT NULL UNIQUE,
    icon VARCHAR(12) NOT NULL DEFAULT '✦',
    sort_order TINYINT UNSIGNED NOT NULL DEFAULT 0
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS users (
    id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    name VARCHAR(80) NOT NULL,
    email VARCHAR(190) NOT NULL UNIQUE,
    password_hash VARCHAR(255) NOT NULL,
    role ENUM('user', 'admin') NOT NULL DEFAULT 'user',
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

ALTER TABLE users
    ADD COLUMN IF NOT EXISTS role ENUM('user', 'admin') NOT NULL DEFAULT 'user';

CREATE TABLE IF NOT EXISTS recipes (
    id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    name VARCHAR(150) NOT NULL,
    description TEXT NOT NULL,
    category VARCHAR(50) NOT NULL,
    duration SMALLINT UNSIGNED NOT NULL,
    difficulty ENUM('Mudah', 'Sedang', 'Sulit') NOT NULL DEFAULT 'Mudah',
    servings TINYINT UNSIGNED NOT NULL DEFAULT 6,
    image VARCHAR(500) NOT NULL DEFAULT 'assets/images/recipe-art.svg',
    ingredients JSON NOT NULL,
    instructions JSON NOT NULL,
    tags JSON NOT NULL,
    featured TINYINT(1) NOT NULL DEFAULT 0,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    INDEX idx_recipe_category (category),
    INDEX idx_recipe_featured (featured),
    UNIQUE KEY uq_recipe_name (name),
    CONSTRAINT fk_recipe_category FOREIGN KEY (category) REFERENCES categories(name)
      ON UPDATE CASCADE ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

ALTER TABLE recipes
    ADD COLUMN IF NOT EXISTS updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP;

ALTER TABLE recipes
    ADD COLUMN IF NOT EXISTS image VARCHAR(500) NOT NULL DEFAULT 'assets/images/recipe-art.svg';

ALTER TABLE recipes
    MODIFY COLUMN image VARCHAR(500) NOT NULL DEFAULT 'assets/images/recipe-art.svg';

-- Store a site-relative image path, for example 'uploads/recipes/bolu-kukus.jpg'.
-- Put the image in uploads/recipes/ or use the admin panel to upload it, then update:
-- UPDATE recipes SET image = 'uploads/recipes/bolu-kukus.jpg' WHERE name = 'Bolu Kukus Mekar';

CREATE TABLE IF NOT EXISTS favorites (
    id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    session_key CHAR(48) NOT NULL,
    recipe_id BIGINT UNSIGNED NOT NULL,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE KEY uq_favorite_session_recipe (session_key, recipe_id),
    CONSTRAINT fk_favorite_recipe FOREIGN KEY (recipe_id) REFERENCES recipes(id)
      ON UPDATE CASCADE ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

