INSERT IGNORE INTO recipes
(name, description, category, duration, difficulty, servings, image, ingredients, instructions, tags, featured)
VALUES
('Bolu Kukus Mekar', 'Bolu kukus lembut dan mekar sempurna, cocok untuk teman minum teh.', 'Cake & Bolu', 60, 'Mudah', 8,
'assets/images/recipe-art.svg',
'[{"amount":"250 g","name":"tepung terigu"},{"amount":"200 g","name":"gula pasir"},{"amount":"2 butir","name":"telur"},{"amount":"200 ml","name":"susu cair"},{"amount":"1 sdt","name":"emulsifier"},{"amount":"1 sdt","name":"baking powder"}]',
'["Panaskan kukusan dan alasi tutupnya dengan kain bersih. Siapkan cetakan bolu kukus dengan kertas.","Kocok telur, gula, dan emulsifier sampai putih kental. Masukkan tepung dan baking powder bergantian dengan susu.","Tuang adonan ke cetakan hingga penuh. Kukus dengan api besar selama 15 menit tanpa membuka tutup."]',
'["Mudah","Tradisional","Favorit"]', 1),
('Brownies Cokelat Moist', 'Brownies cokelat pekat dengan tekstur fudgy dan permukaan mengilap.', 'Cake & Bolu', 45, 'Mudah', 8,
'assets/images/recipe-art.svg',
'[{"amount":"200 g","name":"dark chocolate"},{"amount":"150 g","name":"mentega"},{"amount":"150 g","name":"gula pasir"},{"amount":"3 butir","name":"telur"},{"amount":"100 g","name":"tepung terigu"},{"amount":"30 g","name":"bubuk kakao"}]',
'["Lelehkan dark chocolate dan mentega dengan cara ditim, lalu biarkan hangat.","Aduk telur dan gula hingga rata, tidak perlu mengembang. Tuang cokelat leleh, lalu ayak tepung dan kakao.","Tuang ke loyang beralas kertas. Panggang pada 170°C selama 25–30 menit dan dinginkan sebelum dipotong."]',
'["Mudah","Trending","Cokelat"]', 1),
('Kue Ulang Tahun Cokelat', 'Kue lapis cokelat lembut dengan krim ganache untuk perayaan spesial.', 'Cake & Bolu', 90, 'Sedang', 10,
'assets/images/recipe-art.svg',
'[{"amount":"200 g","name":"tepung terigu"},{"amount":"180 g","name":"gula pasir"},{"amount":"4 butir","name":"telur"},{"amount":"40 g","name":"bubuk kakao"},{"amount":"150 g","name":"cokelat masak"},{"amount":"200 ml","name":"krim kental"}]',
'["Kocok telur dan gula sampai mengembang. Ayak tepung dan kakao, lalu lipat perlahan ke adonan.","Tuang ke dua loyang bulat 18 cm. Panggang pada 170°C selama 25 menit, lalu dinginkan.","Panaskan krim hingga hampir mendidih, tuang ke cokelat cincang dan aduk menjadi ganache. Susun dan hias lapisan kue."]',
'["Sedang","Ulang Tahun","Cokelat"]', 1),
('Cheesecake Lembut', 'Cheesecake panggang lembut dengan dasar biskuit renyah dan rasa keju creamy.', 'Dessert', 90, 'Sedang', 8,
'assets/images/recipe-art.svg',
'[{"amount":"200 g","name":"biskuit gandum"},{"amount":"80 g","name":"mentega leleh"},{"amount":"400 g","name":"cream cheese"},{"amount":"120 g","name":"gula pasir"},{"amount":"2 butir","name":"telur"},{"amount":"120 ml","name":"krim kental"}]',
'["Hancurkan biskuit, campur mentega, tekan ke dasar loyang bongkar pasang dan dinginkan.","Aduk cream cheese dan gula sampai halus. Masukkan telur satu per satu lalu tambahkan krim.","Tuang ke loyang dan panggang dengan teknik au bain-marie pada 150°C selama 60 menit. Dinginkan dan simpan di kulkas."]',
'["Sedang","Keju","Favorit"]', 1),
('Kue Kering Nastar', 'Kue kering klasik berisi selai nanas yang legit dan lumer di mulut.', 'Kue Kering', 120, 'Sedang', 30,
'assets/images/recipe-art.svg',
'[{"amount":"250 g","name":"mentega"},{"amount":"50 g","name":"gula halus"},{"amount":"2 butir","name":"kuning telur"},{"amount":"350 g","name":"tepung terigu"},{"amount":"200 g","name":"selai nanas"},{"amount":"2 butir","name":"kuning telur untuk olesan"}]',
'["Kocok mentega dan gula sebentar sampai rata. Masukkan kuning telur, aduk rata.","Masukkan tepung bertahap. Ambil sedikit adonan, isi selai nanas, lalu bentuk bulat.","Susun di loyang. Panggang pada 150°C selama 20 menit, olesi kuning telur dan panggang lagi 10 menit."]',
'["Mudah","Lebaran","Favorit"]', 1),
('Kue Sus Vla Vanila', 'Kue sus berongga dengan isian vla vanila lembut dan harum.', 'Roti & Pastry', 75, 'Sedang', 12,
'assets/images/recipe-art.svg',
'[{"amount":"125 ml","name":"air"},{"amount":"60 g","name":"mentega"},{"amount":"75 g","name":"tepung terigu"},{"amount":"2 butir","name":"telur"},{"amount":"400 ml","name":"susu cair"},{"amount":"50 g","name":"gula pasir"},{"amount":"30 g","name":"maizena"}]',
'["Didihkan air dan mentega. Matikan api, masukkan tepung, aduk lalu masak sebentar sampai kalis dan dinginkan.","Masukkan telur satu per satu. Semprotkan adonan di loyang dan panggang pada 200°C selama 25 menit tanpa membuka oven.","Masak susu, gula, dan maizena sampai mengental. Dinginkan vla, belah sus dan isi sebelum disajikan."]',
'["Sedang","Vla","Pastry"]', 1),
('Bolu Pandan', 'Bolu pandan harum dengan warna hijau alami dan tekstur sangat lembut.', 'Cake & Bolu', 55, 'Mudah', 8,
'assets/images/recipe-art.svg',
'[{"amount":"200 g","name":"tepung terigu"},{"amount":"180 g","name":"gula pasir"},{"amount":"4 butir","name":"telur"},{"amount":"100 ml","name":"santan"},{"amount":"1 sdt","name":"pasta pandan"},{"amount":"1 sdt","name":"emulsifier"}]',
'["Panaskan oven pada 170°C dan siapkan loyang yang diolesi margarin.","Kocok telur, gula, dan emulsifier hingga kental berjejak. Ayak tepung sedikit demi sedikit.","Masukkan santan dan pandan. Tuang ke loyang lalu panggang 35 menit sampai matang."]',
'["Mudah","Tradisional","Pandan"]', 1),
('Lapis Legit', 'Kue berlapis harum rempah dengan tekstur kaya dan lembut.', 'Cake & Bolu', 180, 'Sulit', 12,
'assets/images/recipe-art.svg',
'[{"amount":"300 g","name":"mentega"},{"amount":"200 g","name":"gula halus"},{"amount":"20 butir","name":"kuning telur"},{"amount":"100 g","name":"tepung terigu"},{"amount":"1 sdm","name":"bumbu spekuk"},{"amount":"2 sdm","name":"susu kental manis"}]',
'["Kocok mentega dan susu kental manis sampai lembut. Di wadah lain kocok kuning telur dan gula sampai mengembang.","Campurkan tepung dan spekuk ke adonan telur, lalu lipat mentega secara bertahap.","Tuang satu lapis tipis ke loyang dan panggang dengan api atas. Ulangi melapis dan memanggang sampai adonan habis."]',
'["Sulit","Premium","Rempah"]', 0),
('Klepon Gula Merah', 'Bola ketan kenyal berisi gula merah cair, disajikan dengan kelapa parut.', 'Kue Tradisional', 40, 'Mudah', 20,
'assets/images/recipe-art.svg',
'[{"amount":"250 g","name":"tepung ketan"},{"amount":"200 ml","name":"air pandan"},{"amount":"100 g","name":"gula merah sisir"},{"amount":"150 g","name":"kelapa parut"},{"amount":"1/2 sdt","name":"garam"}]',
'["Kukus kelapa parut dengan garam selama 10 menit, lalu sisihkan. Uleni tepung ketan dengan air pandan sedikit demi sedikit hingga bisa dibentuk.","Ambil adonan, pipihkan, isi gula merah, lalu bulatkan rapat.","Rebus dalam air mendidih sampai mengapung. Angkat, tiriskan, lalu gulingkan ke kelapa parut."]',
'["Mudah","Tradisional","Ketan"]', 0),
('Onde-onde Wijen', 'Bola ketan bertabur wijen dengan isian kacang hijau manis.', 'Kue Tradisional', 60, 'Sedang', 18,
'assets/images/recipe-art.svg',
'[{"amount":"200 g","name":"kacang hijau kupas"},{"amount":"250 g","name":"tepung ketan"},{"amount":"70 g","name":"gula pasir"},{"amount":"150 ml","name":"air hangat"},{"amount":"100 g","name":"wijen"},{"amount":"1/2 sdt","name":"garam"}]',
'["Rendam kacang hijau, kukus sampai empuk lalu haluskan bersama gula dan garam. Bentuk menjadi bola kecil.","Uleni tepung ketan dengan air hangat sampai lembut. Bungkus bola isi dengan adonan ketan.","Basahi permukaan onde-onde, gulingkan ke wijen dan goreng dengan api kecil sampai kuning keemasan."]',
'["Sedang","Tradisional","Wijen"]', 0),
('Kue Lumpur Kentang', 'Kue lumpur lembut dengan aroma santan, kentang, dan vanila.', 'Kue Tradisional', 50, 'Mudah', 12,
'assets/images/recipe-art.svg',
'[{"amount":"250 g","name":"kentang kukus"},{"amount":"200 g","name":"tepung terigu"},{"amount":"150 g","name":"gula pasir"},{"amount":"2 butir","name":"telur"},{"amount":"300 ml","name":"santan"},{"amount":"50 g","name":"mentega leleh"}]',
'["Haluskan kentang kukus. Kocok telur dan gula sampai larut, lalu masukkan kentang.","Masukkan tepung bergantian dengan santan. Tambahkan mentega leleh dan aduk sampai licin.","Tuang ke cetakan kue lumpur yang sudah dipanaskan. Masak tertutup dengan api kecil hingga matang."]',
'["Mudah","Tradisional","Kentang"]', 0),
('Martabak Manis', 'Martabak tebal bersarang dengan topping cokelat, keju, dan susu.', 'Kue Tradisional', 60, 'Sedang', 6,
'assets/images/recipe-art.svg',
'[{"amount":"250 g","name":"tepung terigu"},{"amount":"300 ml","name":"susu cair"},{"amount":"1 butir","name":"telur"},{"amount":"50 g","name":"gula pasir"},{"amount":"1/2 sdt","name":"soda kue"},{"amount":"secukupnya","name":"mentega, meses, dan keju"}]',
'["Aduk tepung, gula, susu, dan telur sampai licin. Diamkan adonan 30 menit, lalu masukkan soda kue.","Panaskan teflon dengan api kecil. Tuang adonan dan putar hingga membentuk pinggiran.","Tutup hingga permukaan bersarang dan matang. Olesi mentega, tambahkan topping, lalu lipat."]',
'["Sedang","Favorit","Camilan"]', 0),
('Serabi Kuah Kinca', 'Serabi santan berpori dengan siraman kuah gula merah yang harum.', 'Kue Tradisional', 50, 'Mudah', 8,
'assets/images/recipe-art.svg',
'[{"amount":"200 g","name":"tepung beras"},{"amount":"50 g","name":"tepung terigu"},{"amount":"300 ml","name":"santan"},{"amount":"1 sdt","name":"ragi instan"},{"amount":"150 g","name":"gula merah"},{"amount":"1 lembar","name":"daun pandan"}]',
'["Campur tepung, ragi, dan santan sampai halus. Diamkan 30 menit hingga sedikit berbuih.","Masak gula merah, 200 ml santan, pandan, dan sedikit garam sampai larut menjadi kuah kinca.","Tuang adonan ke wajan kecil panas. Masak tertutup dengan api kecil sampai berpori dan matang. Sajikan dengan kinca."]',
'["Mudah","Tradisional","Santan"]', 0),
('Dadar Gulung Isi Kelapa', 'Kulit dadar pandan lembut berisi unti kelapa gula merah.', 'Kue Tradisional', 45, 'Mudah', 10,
'assets/images/recipe-art.svg',
'[{"amount":"200 g","name":"tepung terigu"},{"amount":"1 butir","name":"telur"},{"amount":"450 ml","name":"santan encer"},{"amount":"150 g","name":"kelapa parut"},{"amount":"100 g","name":"gula merah"},{"amount":"1 sdt","name":"pasta pandan"}]',
'["Masak kelapa parut, gula merah, dan sedikit air sampai kering dan harum. Sisihkan.","Campur tepung, telur, santan, dan pandan sampai licin. Saring adonan agar tidak bergerindil.","Buat dadar tipis di teflon. Isi dengan unti kelapa lalu lipat seperti amplop."]',
'["Mudah","Tradisional","Pandan"]', 0),
('Kue Putu Ayu', 'Kue kukus pandan yang lembut dengan lapisan kelapa gurih.', 'Kue Tradisional', 45, 'Mudah', 12,
'assets/images/recipe-art.svg',
'[{"amount":"150 g","name":"tepung terigu"},{"amount":"125 g","name":"gula pasir"},{"amount":"2 butir","name":"telur"},{"amount":"100 ml","name":"santan"},{"amount":"1 sdt","name":"pasta pandan"},{"amount":"100 g","name":"kelapa parut"}]',
'["Kukus kelapa parut dengan sedikit garam. Tekan kelapa ke dasar cetakan putu ayu yang diolesi minyak.","Kocok telur dan gula sampai mengembang. Masukkan tepung dan santan pandan secara bergantian.","Tuang adonan ke cetakan dan kukus 15 menit dengan api sedang."]',
'["Mudah","Tradisional","Kukus"]', 0),
('Kue Talam Ubi', 'Kue talam dua lapis dari ubi manis dan santan yang gurih.', 'Kue Tradisional', 60, 'Sedang', 12,
'assets/images/recipe-art.svg',
'[{"amount":"250 g","name":"ubi kuning kukus"},{"amount":"150 g","name":"tepung tapioka"},{"amount":"100 g","name":"tepung beras"},{"amount":"200 g","name":"gula pasir"},{"amount":"400 ml","name":"santan"},{"amount":"1/2 sdt","name":"garam"}]',
'["Haluskan ubi dan campur dengan sebagian santan, gula, tepung tapioka, dan tepung beras.","Campur sisa santan dengan tepung beras dan garam untuk lapisan putih. Aduk sampai rata.","Tuang adonan ubi ke cetakan dan kukus 10 menit. Tuang lapisan putih di atasnya, kukus kembali 15 menit."]',
'["Sedang","Tradisional","Ubi"]', 0),
('Kue Cucur Gula Merah', 'Kue cucur berserat dan bersarang dengan rasa gula merah yang khas.', 'Kue Tradisional', 55, 'Sedang', 10,
'assets/images/recipe-art.svg',
'[{"amount":"150 g","name":"tepung beras"},{"amount":"50 g","name":"tepung terigu"},{"amount":"150 g","name":"gula merah"},{"amount":"250 ml","name":"air"},{"amount":"1 lembar","name":"daun pandan"},{"amount":"sejumput","name":"garam"}]',
'["Rebus gula merah, air, pandan, dan garam sampai larut. Saring dan biarkan hangat.","Campur tepung beras dan terigu. Tuang larutan gula bertahap sambil dipukul sampai licin, diamkan 1 jam.","Goreng satu sendok sayur adonan di minyak panas secukupnya. Siram bagian tengah dengan minyak sampai matang."]',
'["Sedang","Tradisional","Gula Merah"]', 0),
('Kastengel Keju', 'Kue kering keju gurih dan renyah dengan taburan keju cheddar.', 'Kue Kering', 90, 'Sedang', 35,
'assets/images/recipe-art.svg',
'[{"amount":"200 g","name":"mentega"},{"amount":"2 butir","name":"kuning telur"},{"amount":"250 g","name":"tepung terigu"},{"amount":"150 g","name":"keju cheddar parut"},{"amount":"30 g","name":"maizena"},{"amount":"1 butir","name":"kuning telur untuk olesan"}]',
'["Aduk mentega dan kuning telur sampai rata. Masukkan keju parut.","Tambahkan tepung dan maizena yang sudah diayak, aduk hingga adonan bisa dipulung.","Bentuk memanjang, olesi kuning telur dan taburi keju. Panggang pada 150°C selama 25 menit."]',
'["Sedang","Lebaran","Keju"]', 0),
('Putri Salju', 'Kue kering lembut bertabur gula halus yang lumer saat digigit.', 'Kue Kering', 80, 'Mudah', 30,
'assets/images/recipe-art.svg',
'[{"amount":"250 g","name":"mentega"},{"amount":"60 g","name":"gula halus"},{"amount":"300 g","name":"tepung terigu"},{"amount":"100 g","name":"kacang mede sangrai"},{"amount":"30 g","name":"maizena"},{"amount":"secukupnya","name":"gula donat"}]',
'["Haluskan kacang mede. Aduk mentega dan gula halus hingga rata, lalu masukkan kacang.","Masukkan tepung dan maizena bertahap. Bentuk bulan sabit dan susun di loyang.","Panggang pada 150°C sekitar 25 menit. Saat masih hangat, gulingkan ke gula donat."]',
'["Mudah","Lebaran","Favorit"]', 0),
('Lidah Kucing', 'Kue tipis renyah dengan aroma mentega, nikmat untuk teman minum teh.', 'Kue Kering', 75, 'Sedang', 40,
'assets/images/recipe-art.svg',
'[{"amount":"150 g","name":"mentega"},{"amount":"100 g","name":"gula halus"},{"amount":"100 g","name":"putih telur"},{"amount":"150 g","name":"tepung terigu"},{"amount":"20 g","name":"susu bubuk"},{"amount":"1/2 sdt","name":"vanila"}]',
'["Kocok mentega, gula halus, dan vanila sampai lembut. Masukkan putih telur sedikit demi sedikit.","Ayak tepung dan susu bubuk, lalu lipat ke adonan sampai rata.","Masukkan ke piping bag, cetak memanjang di loyang lidah kucing. Panggang pada 150°C sampai pinggirnya keemasan."]',
'["Sedang","Lebaran","Renyah"]', 0),
('Cookies Choco Chip', 'Cookies renyah di pinggir dan chewy di tengah dengan cokelat melimpah.', 'Kue Kering', 35, 'Mudah', 16,
'assets/images/recipe-art.svg',
'[{"amount":"150 g","name":"mentega"},{"amount":"100 g","name":"gula palem"},{"amount":"1 butir","name":"telur"},{"amount":"220 g","name":"tepung terigu"},{"amount":"150 g","name":"chocolate chips"},{"amount":"1/2 sdt","name":"baking soda"}]',
'["Aduk mentega dan gula palem hingga lembut, masukkan telur lalu aduk rata.","Tambahkan tepung dan baking soda. Masukkan chocolate chips dan dinginkan adonan 20 menit.","Bulatkan adonan di loyang dengan jarak. Panggang pada 175°C selama 12–15 menit."]',
'["Mudah","Cokelat","Cookies"]', 0),
('Bolu Gulung', 'Bolu gulung tipis yang lembut dengan olesan selai pilihan.', 'Cake & Bolu', 50, 'Sedang', 8,
'assets/images/recipe-art.svg',
'[{"amount":"5 butir","name":"telur"},{"amount":"100 g","name":"gula pasir"},{"amount":"100 g","name":"tepung terigu"},{"amount":"100 g","name":"mentega leleh"},{"amount":"150 g","name":"selai stroberi"},{"amount":"1 sdt","name":"emulsifier"}]',
'["Kocok telur, gula, dan emulsifier hingga kental berjejak. Ayak tepung lalu lipat perlahan.","Masukkan mentega leleh. Ratakan adonan pada loyang datar beralas kertas.","Panggang pada 200°C selama 12 menit. Olesi selai saat hangat, gulung rapat dan dinginkan."]',
'["Sedang","Bolu","Selai"]', 0),
('Chiffon Cake Pandan', 'Chiffon cake tinggi, ringan, dan lembut dengan aroma pandan dan santan.', 'Cake & Bolu', 75, 'Sedang', 10,
'assets/images/recipe-art.svg',
'[{"amount":"120 g","name":"tepung terigu"},{"amount":"5 butir","name":"telur, pisahkan putih dan kuning"},{"amount":"100 ml","name":"santan"},{"amount":"60 ml","name":"minyak sayur"},{"amount":"100 g","name":"gula pasir"},{"amount":"1 sdt","name":"pasta pandan"}]',
'["Aduk kuning telur, santan, minyak, pandan, dan tepung hingga halus.","Kocok putih telur sampai berbusa, tambahkan gula bertahap hingga soft peak. Lipat ke adonan kuning telur.","Tuang ke loyang chiffon tanpa olesan. Panggang pada 160°C selama 50 menit lalu balik loyang hingga dingin."]',
'["Sedang","Pandan","Lembut"]', 0),
('Red Velvet Cake', 'Kue red velvet lembut dengan lapisan cream cheese frosting yang segar.', 'Cake & Bolu', 85, 'Sedang', 10,
'assets/images/recipe-art.svg',
'[{"amount":"250 g","name":"tepung terigu"},{"amount":"200 g","name":"gula pasir"},{"amount":"2 butir","name":"telur"},{"amount":"200 ml","name":"buttermilk"},{"amount":"2 sdm","name":"bubuk kakao"},{"amount":"1 sdt","name":"pewarna merah"}]',
'["Aduk tepung, kakao, dan sedikit garam. Kocok gula, telur, buttermilk, pewarna, dan minyak.","Masukkan campuran tepung ke bahan basah sedikit demi sedikit hingga rata.","Bagi ke dua loyang dan panggang pada 170°C selama 25 menit. Dinginkan lalu lapisi frosting cream cheese."]',
'["Sedang","Red Velvet","Perayaan"]', 0),
('Black Forest', 'Kue cokelat berlapis krim dan ceri dengan rasa klasik yang istimewa.', 'Cake & Bolu', 100, 'Sulit', 12,
'assets/images/recipe-art.svg',
'[{"amount":"180 g","name":"tepung terigu"},{"amount":"40 g","name":"bubuk kakao"},{"amount":"5 butir","name":"telur"},{"amount":"180 g","name":"gula pasir"},{"amount":"300 ml","name":"krim kocok"},{"amount":"100 g","name":"ceri"}]',
'["Kocok telur dan gula sampai mengembang. Ayak tepung dan kakao lalu lipat ke adonan.","Panggang dalam loyang bulat pada 170°C selama 30 menit. Dinginkan dan potong menjadi tiga lapisan.","Olesi tiap lapis dengan krim dan ceri, tutup seluruh kue dengan krim lalu hias cokelat serut."]',
'["Sulit","Cokelat","Ulang Tahun"]', 0),
('Tiramisu Cup', 'Dessert kopi dan mascarpone lembut dalam sajian praktis per cup.', 'Dessert', 35, 'Mudah', 6,
'assets/images/recipe-art.svg',
'[{"amount":"200 g","name":"mascarpone"},{"amount":"200 ml","name":"krim kental"},{"amount":"100 g","name":"gula halus"},{"amount":"150 g","name":"ladyfinger"},{"amount":"150 ml","name":"kopi espresso dingin"},{"amount":"2 sdm","name":"bubuk kakao"}]',
'["Kocok krim kental dan gula sampai soft peak. Lipat bersama mascarpone hingga lembut.","Celupkan ladyfinger sebentar ke kopi. Susun di dasar gelas saji.","Tambahkan krim, ulangi lapisan, lalu taburi kakao. Dinginkan di kulkas minimal 2 jam."]',
'["Mudah","Kopi","Dessert"]', 0),
('Banana Cake', 'Kue pisang moist dengan aroma kayu manis yang hangat.', 'Cake & Bolu', 60, 'Mudah', 8,
'assets/images/recipe-art.svg',
'[{"amount":"3 buah","name":"pisang matang"},{"amount":"200 g","name":"tepung terigu"},{"amount":"120 g","name":"gula palem"},{"amount":"2 butir","name":"telur"},{"amount":"100 g","name":"mentega leleh"},{"amount":"1 sdt","name":"baking powder"}]',
'["Lumatkan pisang matang. Aduk bersama telur, gula palem, dan mentega leleh.","Masukkan tepung dan baking powder yang sudah diayak. Aduk secukupnya sampai rata.","Tuang ke loyang dan panggang pada 170°C selama 40 menit."]',
'["Mudah","Pisang","Camilan"]', 0),
('Carrot Cake', 'Kue wortel lembut dengan kayu manis dan topping cream cheese.', 'Cake & Bolu', 70, 'Sedang', 8,
'assets/images/recipe-art.svg',
'[{"amount":"200 g","name":"wortel parut"},{"amount":"200 g","name":"tepung terigu"},{"amount":"150 g","name":"gula palem"},{"amount":"2 butir","name":"telur"},{"amount":"120 ml","name":"minyak sayur"},{"amount":"1 sdt","name":"kayu manis bubuk"}]',
'["Campur tepung, kayu manis, dan baking powder. Kocok telur dan gula sampai larut.","Masukkan minyak, wortel, lalu campuran tepung. Aduk hingga rata.","Panggang pada 170°C selama 40 menit. Dinginkan dan olesi cream cheese frosting."]',
'["Sedang","Wortel","Cream Cheese"]', 0),
('Pukis Cokelat', 'Kue pukis empuk dan harum dengan topping cokelat favorit keluarga.', 'Kue Tradisional', 55, 'Mudah', 14,
'assets/images/recipe-art.svg',
'[{"amount":"250 g","name":"tepung terigu"},{"amount":"150 g","name":"gula pasir"},{"amount":"2 butir","name":"telur"},{"amount":"250 ml","name":"santan"},{"amount":"1 sdt","name":"ragi instan"},{"amount":"secukupnya","name":"meses cokelat"}]',
'["Campur ragi dengan santan hangat. Kocok telur dan gula sampai larut.","Masukkan tepung dan santan ragi bergantian. Diamkan adonan 45 menit hingga mengembang.","Tuang ke cetakan pukis yang sudah panas. Tambahkan meses, tutup dan masak sampai matang."]',
'["Mudah","Tradisional","Cokelat"]', 0),
('Nagasari Pisang', 'Kue pisang kukus berbalut adonan tepung beras dan santan.', 'Kue Tradisional', 60, 'Mudah', 10,
'assets/images/recipe-art.svg',
'[{"amount":"150 g","name":"tepung beras"},{"amount":"50 g","name":"tepung tapioka"},{"amount":"500 ml","name":"santan"},{"amount":"100 g","name":"gula pasir"},{"amount":"3 buah","name":"pisang kepok"},{"amount":"secukupnya","name":"daun pisang"}]',
'["Aduk tepung beras, tapioka, gula, dan santan sampai larut. Masak sambil diaduk hingga mengental.","Potong pisang menjadi beberapa bagian. Siapkan daun pisang yang sudah dilayukan.","Bungkus satu sendok adonan dan potongan pisang dengan daun. Kukus selama 25 menit."]',
'["Mudah","Tradisional","Pisang"]', 0),
('Muffin Blueberry', 'Muffin lembut dengan blueberry segar dan bagian atas yang keemasan.', 'Cake & Bolu', 40, 'Mudah', 8,
'assets/images/recipe-art.svg',
'[{"amount":"200 g","name":"tepung terigu"},{"amount":"100 g","name":"gula pasir"},{"amount":"1 butir","name":"telur"},{"amount":"150 ml","name":"susu cair"},{"amount":"80 ml","name":"minyak sayur"},{"amount":"120 g","name":"blueberry"}]',
'["Aduk tepung, gula, dan baking powder. Di wadah lain campur telur, susu, dan minyak.","Tuang bahan basah ke bahan kering. Aduk singkat, lalu lipat blueberry ke dalam adonan.","Bagi ke cup muffin dan panggang pada 180°C selama 20–25 menit."]',
'["Mudah","Buah","Sarapan"]', 0),
('Roti Sobek Manis', 'Roti sobek empuk yang lembut dan enak disajikan hangat.', 'Roti & Pastry', 120, 'Sedang', 10,
'assets/images/recipe-art.svg',
'[{"amount":"300 g","name":"tepung terigu protein tinggi"},{"amount":"50 g","name":"gula pasir"},{"amount":"1 butir","name":"telur"},{"amount":"160 ml","name":"susu hangat"},{"amount":"1 sdt","name":"ragi instan"},{"amount":"40 g","name":"mentega"}]',
'["Campur tepung, gula, dan ragi. Masukkan telur serta susu sedikit demi sedikit, uleni hingga kalis.","Masukkan mentega dan garam. Uleni sampai elastis, tutup dan fermentasikan 45 menit.","Bagi adonan, bulatkan dan susun dalam loyang. Diamkan 30 menit lalu panggang 180°C selama 20 menit."]',
'["Sedang","Roti","Empuk"]', 0),
('Puding Cokelat', 'Puding cokelat lembut dengan saus vla vanila yang mudah dibuat.', 'Dessert', 25, 'Mudah', 6,
'assets/images/recipe-art.svg',
'[{"amount":"1 bungkus","name":"agar-agar bubuk"},{"amount":"600 ml","name":"susu cair"},{"amount":"100 g","name":"gula pasir"},{"amount":"30 g","name":"bubuk kakao"},{"amount":"100 g","name":"cokelat masak"},{"amount":"1 sdm","name":"maizena untuk vla"}]',
'["Aduk agar-agar, gula, kakao, dan susu hingga larut. Masak sambil diaduk sampai mendidih.","Masukkan cokelat cincang, aduk sampai larut. Tuang ke cetakan dan dinginkan hingga mengeras.","Untuk vla, masak susu, gula, dan maizena sampai mengental. Sajikan bersama puding dingin."]',
'["Mudah","Cokelat","Dessert"]', 0),
('Bolu Kukus Pisang', 'Bolu kukus pisang tanpa oven yang lembut dan praktis untuk camilan.', 'Cake & Bolu', 45, 'Mudah', 8,
'assets/images/recipe-art.svg',
'[{"amount":"3 buah","name":"pisang matang"},{"amount":"200 g","name":"tepung terigu"},{"amount":"120 g","name":"gula pasir"},{"amount":"2 butir","name":"telur"},{"amount":"100 ml","name":"minyak sayur"},{"amount":"1 sdt","name":"baking powder"}]',
'["Lumatkan pisang, lalu aduk dengan telur, gula, dan minyak sampai rata.","Masukkan tepung dan baking powder. Aduk secukupnya sampai tidak ada tepung kering.","Tuang ke loyang beroles minyak. Kukus 30 menit dalam kukusan panas dengan tutup berlapis kain."]',
'["Mudah","Pisang","Kukus"]', 0),
('Kue Apem Gula Merah', 'Apem kukus bertekstur empuk dengan aroma gula merah dan pandan.', 'Kue Tradisional', 70, 'Mudah', 12,
'assets/images/recipe-art.svg',
'[{"amount":"200 g","name":"tepung beras"},{"amount":"50 g","name":"tepung terigu"},{"amount":"150 g","name":"gula merah"},{"amount":"250 ml","name":"santan"},{"amount":"1 sdt","name":"ragi instan"},{"amount":"1 lembar","name":"daun pandan"}]',
'["Rebus gula merah dan pandan dengan santan hingga larut, lalu dinginkan sampai hangat.","Aduk tepung beras, tepung terigu, dan ragi. Tuang larutan santan sambil diaduk hingga licin.","Diamkan adonan 45 menit. Tuang ke cetakan dan kukus 15 menit hingga matang."]',
'["Mudah","Tradisional","Gula Merah"]', 0);

INSERT IGNORE INTO recipes
(name, description, category, duration, difficulty, servings, image, ingredients, instructions, tags, featured)
VALUES
('Bolu Kukus Gula Merah', 'Bolu kukus mekar dengan aroma gula merah, santan, dan pandan khas jajanan pasar.', 'Kue Kukus Nusantara', 55, 'Mudah', 10,
'assets/images/recipe-art.svg',
'[{"amount":"200 g","name":"gula merah"},{"amount":"200 ml","name":"santan"},{"amount":"250 g","name":"tepung terigu"},{"amount":"1 butir","name":"telur"},{"amount":"1/2 sdt","name":"soda kue"},{"amount":"2 lembar","name":"daun pandan"}]',
'["Rebus gula merah, santan, dan pandan sampai larut. Saring lalu dinginkan.","Aduk tepung dan soda kue. Masukkan telur dan larutan gula sedikit demi sedikit sampai adonan licin.","Tuang ke cetakan sampai penuh. Kukus 20 menit dengan api besar dan tutup kukusan berlapis kain."]',
'["Lokal Indonesia","Kukus","Gula Merah","Jajanan Pasar"]', 1),
('Bolu Kukus Santan', 'Bolu kukus sederhana yang lembut, wangi santan, dan mudah dibuat tanpa oven.', 'Kue Kukus Nusantara', 50, 'Mudah', 8,
'assets/images/recipe-art.svg',
'[{"amount":"200 g","name":"tepung terigu"},{"amount":"160 g","name":"gula pasir"},{"amount":"2 butir","name":"telur"},{"amount":"180 ml","name":"santan"},{"amount":"1 sdt","name":"emulsifier"},{"amount":"1/2 sdt","name":"vanili"}]',
'["Panaskan kukusan sampai beruap banyak dan siapkan cetakan beralas kertas.","Kocok telur, gula, dan emulsifier sampai putih kental. Masukkan tepung dan santan bergantian.","Tuang adonan ke cetakan dan kukus 15 menit dengan api besar. Jangan membuka tutup kukusan."]',
'["Lokal Indonesia","Kukus","Santan","Jajanan Pasar"]', 1),
('Bolu Tape Singkong', 'Bolu panggang lembut dengan rasa tape singkong yang legit dan harum.', 'Cake & Bolu', 65, 'Mudah', 10,
'assets/images/recipe-art.svg',
'[{"amount":"250 g","name":"tape singkong matang"},{"amount":"200 g","name":"tepung terigu"},{"amount":"150 g","name":"gula pasir"},{"amount":"4 butir","name":"telur"},{"amount":"150 g","name":"mentega leleh"},{"amount":"1 sdt","name":"emulsifier"}]',
'["Buang sumbu tape lalu lumatkan bersama sedikit santan sampai halus.","Kocok telur, gula, dan emulsifier hingga mengembang. Masukkan tape, tepung terigu, lalu mentega leleh.","Tuang ke loyang dan panggang pada 170°C selama 35–40 menit hingga matang."]',
'["Lokal Indonesia","Tape","Bolu","Tradisional"]', 1),
('Bolu Karamel Sarang Semut', 'Bolu karamel berongga dengan aroma karamel yang kuat dan tekstur kenyal lembut.', 'Cake & Bolu', 75, 'Sedang', 10,
'assets/images/recipe-art.svg',
'[{"amount":"200 g","name":"gula pasir untuk karamel"},{"amount":"250 ml","name":"air panas"},{"amount":"150 g","name":"tepung terigu"},{"amount":"100 g","name":"tepung tapioka"},{"amount":"4 butir","name":"telur"},{"amount":"100 g","name":"margarin leleh"},{"amount":"100 g","name":"susu kental manis"}]',
'["Panaskan gula dengan api kecil hingga menjadi karamel. Tuang air panas perlahan, aduk sampai larut lalu dinginkan.","Aduk telur dan susu kental manis, masukkan tepung terigu dan tapioka yang diayak.","Tuang larutan karamel dan margarin, aduk rata lalu panggang pada 170°C selama 45 menit."]',
'["Lokal Indonesia","Karamel","Bolu","Tradisional"]', 0),
('Bika Ambon Medan', 'Kue berserat khas Medan dengan aroma pandan dan serai yang harum.', 'Kue Basah Nusantara', 100, 'Sulit', 12,
'assets/images/recipe-art.svg',
'[{"amount":"300 ml","name":"santan"},{"amount":"2 batang","name":"serai"},{"amount":"6 lembar","name":"daun jeruk"},{"amount":"150 g","name":"tepung tapioka"},{"amount":"70 g","name":"tepung sagu"},{"amount":"8 butir","name":"kuning telur"},{"amount":"1 sdt","name":"ragi instan"}]',
'["Rebus santan, serai, dan daun jeruk sampai harum. Saring dan dinginkan hingga hangat.","Campur tapioka, sagu, gula, dan ragi. Tuang santan sedikit demi sedikit, lalu diamkan 1 jam.","Masukkan kuning telur dan aduk rata. Tuang ke loyang panas yang dioles tipis, panggang sampai bersarang dan matang."]',
'["Lokal Indonesia","Medan","Santan","Oleh-oleh"]', 1),
('Lapis Surabaya', 'Kue lapis kuning dan cokelat yang lembut, klasik untuk sajian keluarga.', 'Cake & Bolu', 90, 'Sedang', 12,
'assets/images/recipe-art.svg',
'[{"amount":"12 butir","name":"telur"},{"amount":"250 g","name":"gula pasir"},{"amount":"250 g","name":"mentega"},{"amount":"150 g","name":"tepung terigu"},{"amount":"25 g","name":"bubuk kakao"},{"amount":"150 g","name":"selai stroberi"}]',
'["Kocok mentega hingga pucat dan lembut. Di wadah lain kocok telur dan gula hingga mengembang.","Masukkan tepung ke adonan telur, lalu lipat mentega. Bagi adonan; campur satu bagian dengan kakao.","Panggang tiap lapisan di loyang terpisah pada 180°C selama 20 menit. Tumpuk bergantian dengan selai."]',
'["Lokal Indonesia","Surabaya","Bolu","Klasik"]', 0),
('Kue Pepe Betawi', 'Kue lapis kenyal warna-warni dari tepung sagu dan santan, jajanan pasar Betawi.', 'Kue Kukus Nusantara', 90, 'Sedang', 16,
'assets/images/recipe-art.svg',
'[{"amount":"250 g","name":"tepung sagu"},{"amount":"100 g","name":"tepung beras"},{"amount":"200 g","name":"gula pasir"},{"amount":"700 ml","name":"santan"},{"amount":"2 lembar","name":"daun pandan"},{"amount":"secukupnya","name":"pewarna makanan"}]',
'["Rebus santan, gula, dan pandan hingga gula larut. Dinginkan dan saring.","Campur tepung sagu serta tepung beras. Tuang santan sedikit demi sedikit sambil diaduk hingga licin.","Bagi adonan dan beri warna. Tuang selapis demi selapis ke loyang, kukus 5 menit setiap lapisan sampai habis."]',
'["Lokal Indonesia","Betawi","Kukus","Jajanan Pasar"]', 0),
('Kue Pancong Kelapa', 'Kue tradisional Betawi dari kelapa parut dengan pinggiran garing dan bagian tengah gurih.', 'Jajanan Pasar', 35, 'Mudah', 12,
'assets/images/recipe-art.svg',
'[{"amount":"150 g","name":"tepung beras"},{"amount":"200 g","name":"kelapa parut"},{"amount":"250 ml","name":"santan"},{"amount":"1 sdt","name":"garam"},{"amount":"2 sdm","name":"gula pasir untuk taburan"}]',
'["Campur tepung beras, kelapa parut, garam, dan santan hingga menjadi adonan kental.","Panaskan cetakan pancong dan olesi sedikit minyak. Tuang adonan hingga hampir penuh.","Panggang tertutup dengan api kecil sampai bagian bawah kecokelatan dan bagian atas matang. Taburi gula."]',
'["Lokal Indonesia","Betawi","Kelapa","Jajanan Pasar"]', 1),
('Kue Rangi Betawi', 'Jajanan Betawi dari sagu dan kelapa dengan saus gula merah kental.', 'Jajanan Pasar', 35, 'Mudah', 10,
'assets/images/recipe-art.svg',
'[{"amount":"200 g","name":"tepung sagu"},{"amount":"150 g","name":"kelapa parut"},{"amount":"1/2 sdt","name":"garam"},{"amount":"150 g","name":"gula merah"},{"amount":"200 ml","name":"air"},{"amount":"1 sdm","name":"maizena"}]',
'["Aduk sagu, kelapa, dan garam sampai berbutir lembap. Sangrai di cetakan rangi panas hingga padat dan harum.","Rebus gula merah dengan air sampai larut, saring, lalu masak kembali.","Tambahkan maizena yang dilarutkan sedikit air. Aduk sampai saus mengental, sajikan di atas kue rangi."]',
'["Lokal Indonesia","Betawi","Sagu","Jajanan Pasar"]', 0),
('Wingko Babat', 'Kue kelapa panggang khas Babat yang harum, legit, dan sedikit kenyal.', 'Kue Basah Nusantara', 55, 'Mudah', 12,
'assets/images/recipe-art.svg',
'[{"amount":"250 g","name":"kelapa parut"},{"amount":"150 g","name":"tepung ketan"},{"amount":"150 g","name":"gula pasir"},{"amount":"100 ml","name":"santan"},{"amount":"1/2 sdt","name":"garam"},{"amount":"1 butir","name":"kuning telur"}]',
'["Campur kelapa, tepung ketan, gula, dan garam hingga rata.","Tuang santan sedikit demi sedikit sampai adonan dapat dipulung. Bentuk bulat pipih.","Panggang di teflon api kecil atau oven 170°C. Balik hingga kedua sisi kecokelatan dan matang."]',
'["Lokal Indonesia","Babat","Kelapa","Oleh-oleh"]', 1),
('Getuk Lindri', 'Getuk singkong warna-warni yang lembut dengan taburan kelapa parut.', 'Jajanan Pasar', 45, 'Mudah', 10,
'assets/images/recipe-art.svg',
'[{"amount":"500 g","name":"singkong"},{"amount":"100 g","name":"gula pasir"},{"amount":"1/2 sdt","name":"garam"},{"amount":"1/2 sdt","name":"vanili"},{"amount":"150 g","name":"kelapa parut"},{"amount":"secukupnya","name":"pewarna makanan"}]',
'["Kukus singkong yang sudah dikupas sampai empuk. Selagi panas, haluskan bersama gula, garam, dan vanili.","Bagi adonan dan beri warna sesuai selera. Giling atau bentuk memanjang lalu potong-potong.","Kukus kelapa parut dengan sedikit garam. Sajikan getuk dengan taburan kelapa."]',
'["Lokal Indonesia","Singkong","Jajanan Pasar","Tradisional"]', 1),
('Lupis Ketan', 'Ketan pulen berbentuk segitiga dengan kelapa parut dan saus gula merah.', 'Jajanan Pasar', 100, 'Sedang', 10,
'assets/images/recipe-art.svg',
'[{"amount":"300 g","name":"beras ketan"},{"amount":"1/2 sdt","name":"garam"},{"amount":"secukupnya","name":"daun pisang"},{"amount":"150 g","name":"kelapa parut"},{"amount":"200 g","name":"gula merah"},{"amount":"150 ml","name":"air"}]',
'["Rendam beras ketan 2 jam, tiriskan, lalu campur dengan garam.","Bungkus ketan berbentuk segitiga menggunakan daun pisang. Rebus dalam air banyak selama 90 menit.","Rebus gula merah dan air hingga menjadi saus. Sajikan lupis dengan kelapa parut kukus dan saus gula merah."]',
'["Lokal Indonesia","Ketan","Jajanan Pasar","Gula Merah"]', 0),
('Cenil Singkong', 'Camilan kenyal berwarna-warni dari tapioka dengan kelapa dan gula merah.', 'Jajanan Pasar', 45, 'Mudah', 8,
'assets/images/recipe-art.svg',
'[{"amount":"250 g","name":"tepung tapioka"},{"amount":"150 ml","name":"air panas"},{"amount":"1/2 sdt","name":"garam"},{"amount":"150 g","name":"kelapa parut"},{"amount":"150 g","name":"gula merah"},{"amount":"secukupnya","name":"pewarna makanan"}]',
'["Campur tapioka dan garam. Tuang air panas sedikit demi sedikit sambil diaduk hingga menjadi adonan kenyal.","Bagi adonan, beri warna, lalu bentuk memanjang atau bulat kecil.","Rebus sampai cenil mengapung. Gulingkan ke kelapa parut kukus dan sajikan dengan gula merah cair."]',
'["Lokal Indonesia","Singkong","Jajanan Pasar","Kenyal"]', 0),
('Wajik Ketan Gula Merah', 'Wajik ketan manis legit dengan santan dan gula merah, sajian tradisional Nusantara.', 'Kue Basah Nusantara', 90, 'Sedang', 12,
'assets/images/recipe-art.svg',
'[{"amount":"300 g","name":"beras ketan"},{"amount":"200 g","name":"gula merah"},{"amount":"250 ml","name":"santan kental"},{"amount":"2 lembar","name":"daun pandan"},{"amount":"1/2 sdt","name":"garam"}]',
'["Rendam ketan 2 jam, tiriskan, lalu kukus 20 menit hingga setengah matang.","Masak santan, gula merah, pandan, dan garam sampai kental. Masukkan ketan kukus.","Aduk terus dengan api kecil sampai santan terserap dan adonan kalis. Ratakan di loyang, dinginkan, lalu potong."]',
'["Lokal Indonesia","Ketan","Gula Merah","Tradisional"]', 0),
('Kue Tiwul Gula Merah', 'Tiwul kukus dari singkong kering dengan kelapa parut dan gula merah.', 'Kue Basah Nusantara', 55, 'Mudah', 8,
'assets/images/recipe-art.svg',
'[{"amount":"300 g","name":"tepung gaplek atau tiwul kering"},{"amount":"200 ml","name":"air"},{"amount":"100 g","name":"gula merah sisir"},{"amount":"150 g","name":"kelapa parut"},{"amount":"1/2 sdt","name":"garam"}]',
'["Percikkan air ke tepung gaplek sedikit demi sedikit sambil diaduk sampai berbutir lembap.","Kukus tiwul bersama gula merah sisir selama 25 menit sampai matang dan harum.","Kukus kelapa dengan garam. Sajikan tiwul hangat dengan kelapa parut."]',
'["Lokal Indonesia","Singkong","Jajanan Pasar","Tradisional"]', 0),
('Kue Bugis Mandi', 'Kue ketan isi unti kelapa yang disajikan dalam siraman saus santan gurih.', 'Kue Basah Nusantara', 65, 'Sedang', 10,
'assets/images/recipe-art.svg',
'[{"amount":"200 g","name":"tepung ketan"},{"amount":"150 ml","name":"santan hangat"},{"amount":"150 g","name":"kelapa parut"},{"amount":"100 g","name":"gula merah"},{"amount":"250 ml","name":"santan untuk saus"},{"amount":"1 sdm","name":"tepung beras"}]',
'["Masak kelapa parut dan gula merah sampai menjadi unti yang agak kering. Dinginkan.","Uleni tepung ketan dengan santan hangat hingga kalis. Isi adonan dengan unti lalu bulatkan.","Kukus kue 15 menit. Masak santan dan tepung beras dengan sedikit garam sampai kental, siramkan saat disajikan."]',
'["Lokal Indonesia","Ketan","Kelapa","Jajanan Pasar"]', 0),
('Kue Mendut Ketan', 'Kue ketan lembut berisi kelapa gula merah dengan saus santan gurih.', 'Kue Basah Nusantara', 60, 'Sedang', 10,
'assets/images/recipe-art.svg',
'[{"amount":"250 g","name":"tepung ketan"},{"amount":"180 ml","name":"santan hangat"},{"amount":"150 g","name":"kelapa parut"},{"amount":"100 g","name":"gula merah"},{"amount":"200 ml","name":"santan untuk saus"},{"amount":"secukupnya","name":"daun pisang"}]',
'["Masak kelapa parut dan gula merah hingga gula larut dan isian mengering.","Uleni tepung ketan dengan santan hingga dapat dipulung. Pipihkan, isi kelapa, lalu bulatkan.","Bungkus tiap kue dengan daun pisang dan siram sedikit santan. Kukus selama 20 menit."]',
'["Lokal Indonesia","Ketan","Kelapa","Tradisional"]', 0),
('Kue Koci Ketan', 'Kue tradisional berbungkus daun pisang dengan kulit ketan dan isian unti kelapa.', 'Kue Basah Nusantara', 60, 'Sedang', 10,
'assets/images/recipe-art.svg',
'[{"amount":"250 g","name":"tepung ketan"},{"amount":"200 ml","name":"santan hangat"},{"amount":"150 g","name":"kelapa parut"},{"amount":"100 g","name":"gula merah"},{"amount":"1/2 sdt","name":"garam"},{"amount":"secukupnya","name":"daun pisang"}]',
'["Masak kelapa parut dan gula merah dengan sedikit air sampai menjadi unti. Dinginkan.","Campur tepung ketan dengan santan dan garam. Uleni sampai lembut, ambil sedikit dan isi dengan unti.","Bungkus dengan daun pisang, lipat rapat, lalu kukus 25 menit sampai matang."]',
'["Lokal Indonesia","Ketan","Kelapa","Jajanan Pasar"]', 0),
('Apem Selong', 'Apem berongga khas Jawa dengan pinggiran tipis dan aroma santan.', 'Kue Kukus Nusantara', 60, 'Sedang', 10,
'assets/images/recipe-art.svg',
'[{"amount":"200 g","name":"tepung beras"},{"amount":"50 g","name":"tepung terigu"},{"amount":"100 g","name":"gula pasir"},{"amount":"250 ml","name":"santan hangat"},{"amount":"1 sdt","name":"ragi instan"},{"amount":"1 butir","name":"telur"}]',
'["Larutkan ragi dan satu sendok gula dalam sedikit santan hangat. Diamkan 10 menit.","Campur tepung beras, tepung terigu, sisa gula, telur, dan santan. Aduk hingga licin lalu diamkan 45 menit.","Tuang ke wajan kecil panas. Tekan bagian tengah agar pinggiran terbentuk, tutup dan masak sampai matang."]',
'["Lokal Indonesia","Jawa","Santan","Jajanan Pasar"]', 0),
('Serabi Solo', 'Serabi tipis lembut dengan santan gurih dan aroma pandan khas Solo.', 'Kue Basah Nusantara', 45, 'Mudah', 10,
'assets/images/recipe-art.svg',
'[{"amount":"200 g","name":"tepung beras"},{"amount":"1 sdm","name":"tepung terigu"},{"amount":"400 ml","name":"santan"},{"amount":"1 sdm","name":"gula pasir"},{"amount":"1/2 sdt","name":"ragi instan"},{"amount":"1 lembar","name":"daun pandan"}]',
'["Rebus santan dengan pandan sampai harum, dinginkan hingga hangat.","Aduk tepung, gula, dan ragi. Tuang santan sambil diaduk hingga licin, diamkan 30 menit.","Tuang sedikit adonan ke wajan kecil. Masak api kecil hingga berpori dan pinggirnya matang."]',
'["Lokal Indonesia","Solo","Santan","Jajanan Pasar"]', 0),
('Kue Sagu Keju', 'Kue kering sagu harum, renyah, dan gurih dengan keju parut.', 'Kue Kering Nusantara', 70, 'Mudah', 30,
'assets/images/recipe-art.svg',
'[{"amount":"300 g","name":"tepung sagu"},{"amount":"100 g","name":"mentega"},{"amount":"100 g","name":"gula halus"},{"amount":"1 butir","name":"kuning telur"},{"amount":"100 g","name":"keju cheddar parut"},{"amount":"50 ml","name":"santan"}]',
'["Sangrai tepung sagu dengan daun pandan hingga ringan, lalu dinginkan.","Kocok mentega dan gula sebentar. Masukkan kuning telur, keju, santan, dan tepung sagu.","Semprotkan adonan di loyang lalu panggang pada 150°C selama 25 menit sampai bagian bawah keemasan."]',
'["Lokal Indonesia","Kue Kering","Keju","Lebaran"]', 1),
('Kue Semprit Mawar', 'Kue semprit renyah berbentuk bunga dengan hiasan selai merah di tengah.', 'Kue Kering Nusantara', 60, 'Mudah', 30,
'assets/images/recipe-art.svg',
'[{"amount":"250 g","name":"tepung terigu"},{"amount":"150 g","name":"mentega"},{"amount":"100 g","name":"gula halus"},{"amount":"2 butir","name":"kuning telur"},{"amount":"50 g","name":"maizena"},{"amount":"secukupnya","name":"selai stroberi"}]',
'["Kocok mentega dan gula halus sampai lembut, masukkan kuning telur.","Masukkan tepung terigu dan maizena yang telah diayak. Aduk sampai adonan bisa disemprot.","Cetak bentuk bunga di loyang, beri selai di tengah, lalu panggang pada 150°C selama 20 menit."]',
'["Lokal Indonesia","Kue Kering","Lebaran","Mudah"]', 0),
('Kue Keciput Wijen', 'Kue kering wijen mungil yang renyah dengan rasa gurih-manis.', 'Kue Kering Nusantara', 60, 'Mudah', 30,
'assets/images/recipe-art.svg',
'[{"amount":"250 g","name":"tepung ketan"},{"amount":"1 butir","name":"telur"},{"amount":"75 g","name":"gula pasir"},{"amount":"100 ml","name":"santan"},{"amount":"100 g","name":"wijen"},{"amount":"1/2 sdt","name":"garam"}]',
'["Aduk telur dan gula sampai gula larut. Masukkan santan dan garam.","Tambahkan tepung ketan sedikit demi sedikit hingga adonan dapat dibentuk. Bentuk bulatan kecil.","Gulingkan ke wijen, tekan agar menempel, lalu goreng api kecil hingga keemasan dan renyah."]',
'["Lokal Indonesia","Kue Kering","Wijen","Lebaran"]', 0),
('Kue Satu Kacang Hijau', 'Kue kering tradisional dari kacang hijau sangrai yang lembut dan mudah lumer.', 'Kue Kering Nusantara', 55, 'Mudah', 25,
'assets/images/recipe-art.svg',
'[{"amount":"250 g","name":"kacang hijau kupas"},{"amount":"100 g","name":"gula halus"},{"amount":"2 sdm","name":"air matang"},{"amount":"1/4 sdt","name":"garam"},{"amount":"1/2 sdt","name":"vanili"}]',
'["Sangrai kacang hijau hingga matang dan harum, dinginkan lalu haluskan dan ayak.","Campur bubuk kacang hijau, gula, garam, dan vanili. Percikkan air sedikit demi sedikit sampai adonan dapat dipadatkan.","Tekan adonan ke cetakan kue satu, keluarkan, lalu panggang suhu rendah 130°C selama 15 menit."]',
'["Lokal Indonesia","Kue Kering","Kacang Hijau","Tradisional"]', 0),
('Bolu Kojo Palembang', 'Bolu hijau khas Palembang dengan pandan, santan, dan aroma daun suji.', 'Cake & Bolu', 75, 'Sedang', 10,
'assets/images/recipe-art.svg',
'[{"amount":"250 g","name":"tepung terigu"},{"amount":"200 g","name":"gula pasir"},{"amount":"4 butir","name":"telur"},{"amount":"400 ml","name":"santan"},{"amount":"100 ml","name":"sari pandan dan suji"},{"amount":"75 g","name":"mentega leleh"}]',
'["Kocok telur dan gula sampai gula larut dan adonan sedikit berbusa.","Masukkan tepung bertahap, lalu tuang santan dan sari pandan-suji. Aduk sampai licin.","Tambahkan mentega leleh. Tuang ke loyang dan panggang pada 170°C sekitar 50 menit hingga matang."]',
'["Lokal Indonesia","Palembang","Pandan","Oleh-oleh"]', 1),
('Kue Gandus Palembang', 'Kue gurih dari tepung beras dan santan, disajikan dengan taburan bawang dan cabai.', 'Kue Kukus Nusantara', 50, 'Mudah', 10,
'assets/images/recipe-art.svg',
'[{"amount":"200 g","name":"tepung beras"},{"amount":"600 ml","name":"santan"},{"amount":"1 sdt","name":"garam"},{"amount":"2 siung","name":"bawang putih halus"},{"amount":"2 sdm","name":"ebi sangrai"},{"amount":"secukupnya","name":"daun bawang dan bawang goreng"}]',
'["Aduk tepung beras, santan, garam, dan bawang putih sampai tidak bergerindil.","Masak adonan sambil diaduk hingga mengental. Tuang ke loyang tahan panas.","Kukus 25 menit hingga padat. Taburi ebi, daun bawang, dan bawang goreng sebelum dipotong."]',
'["Lokal Indonesia","Palembang","Gurih","Kukus"]', 0);

UPDATE recipes
SET tags = JSON_ARRAY_APPEND(tags, '$', 'Lokal Indonesia')
WHERE name IN (
    'Bolu Kukus Mekar', 'Kue Kering Nastar', 'Bolu Pandan',
    'Klepon Gula Merah', 'Onde-onde Wijen', 'Kue Lumpur Kentang',
    'Serabi Kuah Kinca', 'Dadar Gulung Isi Kelapa', 'Kue Putu Ayu',
    'Kue Talam Ubi', 'Kue Cucur Gula Merah', 'Pukis Cokelat',
    'Nagasari Pisang', 'Kue Apem Gula Merah', 'Bolu Kukus Pisang',
    'Lapis Legit', 'Martabak Manis', 'Kastengel Keju',
    'Putri Salju', 'Lidah Kucing', 'Bolu Gulung'
)
AND NOT JSON_CONTAINS(tags, '"Lokal Indonesia"');

UPDATE recipes
SET instructions = JSON_ARRAY(
    'Kukus kelapa parut dengan garam selama 10 menit, lalu sisihkan. Uleni tepung ketan dengan air pandan sedikit demi sedikit hingga bisa dibentuk.',
    'Ambil adonan, pipihkan, isi gula merah, lalu bulatkan rapat.',
    'Rebus dalam air mendidih sampai mengapung. Angkat, tiriskan, lalu gulingkan ke kelapa parut.'
)
WHERE name = 'Klepon Gula Merah';

